import static com.android.SdkConstants.*;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;

public class TextFieldDetector extends LayoutDetector {
    public static final Issue ISSUE = Issue.create(
        "TextFields",
        "Missing `inputType`",
        "Providing an `inputType` attribute on a text field improves usability ...",
        Category.USABILITY,
        5,
        Severity.WARNING,
        new Implementation(TextFieldDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(
                AUTO_COMPLETE_TEXT_VIEW,
                EDIT_TEXT,
                EXTRACT_EDIT_TEXT,
                MULTI_AUTO_COMPLETE_TEXT_VIEW);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Attr attribute = element.getAttributeNodeNS(ANDROID_URI, ATTR_INPUT_TYPE);
        String inputType = attribute == null ? null : attribute.getValue();
        if (inputType == null) {
            context.report(ISSUE, attribute, context.getLocation(element),
                "This text field does not specify an inputType");
            return;
        }

        // If inputType is "text", all hints are accepted.
        if (inputType.equals(VAL_TEXT)) {
            return;
        }

        String id = element.getAttributeNS(ANDROID_URI, ATTR_ID);
        if (id != null && !id.isEmpty()) {
            int index = id.lastIndexOf('/');
            if (index != -1) {
                id = id.substring(index + 1);
            }
            id = id.toLowerCase(Locale.US);
            if (id.contains("phone") && !inputType.contains("phone")) {
                context.report(...);
            } else if (id.contains("email") && !inputType.contains("email")) {
                context.report(...);
            }
        }
    }
}
