public static boolean containsWord(String name, String word, boolean allowPrefix, boolean allowSuffix) {
    if (name == null || word == null || word.isEmpty()) {
        return false;
    }
    String lowerName = name.toLowerCase(Locale.US);
    String lowerWord = word.toLowerCase(Locale.US);
    int wordLength = lowerWord.length();
    int index = lowerName.indexOf(lowerWord);
    while (index != -1) {
        int end = index + wordLength;
        boolean hasPrefix = index > 0 && Character.isJavaIdentifierPart(lowerName.charAt(index - 1));
        boolean hasSuffix = end < lowerName.length() && Character.isJavaIdentifierPart(lowerName.charAt(end));
        if ((!hasPrefix || allowPrefix) && (!hasSuffix || allowSuffix)) {
            return true;
        }
        index = lowerName.indexOf(lowerWord, index + 1);
    }
    return false;
}
