public static boolean containsWord(String name, String word, boolean allowPrefix, boolean allowSuffix) {
    int wordLength = word.length();
    int nameLength = name.length();
    if (wordLength == 0) {
        return false;
    }
    for (int index = 0; index <= nameLength - wordLength; index++) {
        if (name.regionMatches(true, index, word, 0, wordLength)) {
            boolean prefixBoundary = index == 0 || !Character.isJavaIdentifierPart(name.charAt(index - 1));
            boolean suffixBoundary = index + wordLength == nameLength || !Character.isJavaIdentifierPart(name.charAt(index + wordLength));
            if ((allowPrefix || prefixBoundary) && (allowSuffix || suffixBoundary)) {
                return true;
            }
        }
    }
    return false;
}
